import '@servicenow/sdk/global'
import { action, Flow, trigger, wfa, FlowObject, FlowArray } from '@servicenow/sdk/automation'
import { BooleanColumn, IntegerColumn, StringColumn } from '@servicenow/sdk/core'

/**
 * Comprehensive Test Flow for FlowObject and FlowArray in setFlowVariables
 *
 * This flow tests all possible scenarios:
 * 1. Happy Path: Object literals assigned to FlowObject/FlowArray
 * 2. Datapills: Using trigger data in complex objects
 * 3. Edge Cases: Empty values, null values, primitive to FlowObject assignment
 * 4. Nested Structures: FlowObject within FlowObject, FlowArray within FlowObject
 * 5. Mixed Values: Combining literals and datapills
 * 6. Template Expressions: Using template strings in complex objects
 */
export const comprehensiveFlowObjectTest = Flow(
    {
        $id: Now.ID['comprehensive_complex_types_test'],
        name: 'Comprehensive Test - FlowObject and FlowArray',
        description: 'Tests all possible cases for FlowObject and FlowArray in setFlowVariables',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            // ==== Simple FlowObject ====
            userInfo: FlowObject({
                fields: {
                    name: StringColumn({
                        label: 'Name',
                        mandatory: false,
                    }),
                    email: StringColumn({
                        label: 'Email',
                        mandatory: false,
                    }),
                    age: IntegerColumn({
                        label: 'Age',
                        mandatory: false,
                    }),
                    isActive: BooleanColumn({
                        label: 'Is Active',
                        mandatory: false,
                    }),
                },
                label: 'User Info',
                mandatory: false,
            }),

            // ==== Simple FlowArray (FlowObject elements) ====
            tags: FlowArray({
                label: 'Tags',
                mandatory: false,
                elementType: FlowObject({
                    fields: {
                        value: StringColumn({
                            label: 'Tag Value',
                            mandatory: false,
                        }),
                    },
                    label: 'Tag',
                    mandatory: false,
                }),
                childName: 'tag',
            }),

            // ==== Nested FlowObject ====
            config: FlowObject({
                fields: {
                    settings: FlowObject({
                        fields: {
                            timeout: IntegerColumn({
                                label: 'Timeout',
                                mandatory: false,
                            }),
                            retries: IntegerColumn({
                                label: 'Retries',
                                mandatory: false,
                            }),
                            enabled: BooleanColumn({
                                label: 'Enabled',
                                mandatory: false,
                            }),
                        },
                        label: 'Settings',
                        mandatory: false,
                    }),
                    description: StringColumn({
                        label: 'Description',
                        mandatory: false,
                    }),
                },
                label: 'Config',
                mandatory: false,
            }),

            // ==== FlowObject with nested FlowArray ====
            project: FlowObject({
                fields: {
                    name: StringColumn({
                        label: 'Project Name',
                        mandatory: false,
                    }),
                    tasks: FlowArray({
                        label: 'Tasks',
                        mandatory: false,
                        elementType: FlowObject({
                            fields: {
                                taskName: StringColumn({
                                    label: 'Task Name',
                                    mandatory: false,
                                }),
                            },
                            label: 'Task',
                            mandatory: false,
                        }),
                        childName: 'task',
                    }),
                },
                label: 'Project',
                mandatory: false,
            }),

            // ==== FlowObject for testing empty/null values ====
            partialData: FlowObject({
                fields: {
                    field1: StringColumn({
                        label: 'Field 1',
                        mandatory: false,
                    }),
                    field2: StringColumn({
                        label: 'Field 2',
                        mandatory: false,
                    }),
                    field3: IntegerColumn({
                        label: 'Field 3',
                        mandatory: false,
                    }),
                },
                label: 'Partial Data',
                mandatory: false,
            }),

            // ==== FlowObject for testing datapill assignment (primitive to FlowObject) ====
            callerData: FlowObject({
                fields: {
                    userId: StringColumn({
                        label: 'User ID',
                        mandatory: false,
                    }),
                    userName: StringColumn({
                        label: 'User Name',
                        mandatory: false,
                    }),
                },
                label: 'Caller Data',
                mandatory: false,
            }),

            // ==== FlowArray for testing empty array ====
            emptyList: FlowArray({
                label: 'Empty List',
                mandatory: false,
                elementType: FlowObject({
                    fields: {
                        item: StringColumn({
                            label: 'Item',
                            mandatory: false,
                        }),
                    },
                    label: 'List Item',
                    mandatory: false,
                }),
                childName: 'listItem',
            }),

            // ==== FlowObject for testing mixed literals and datapills ====
            mixedData: FlowObject({
                fields: {
                    staticValue: StringColumn({
                        label: 'Static Value',
                        mandatory: false,
                    }),
                    dynamicValue: StringColumn({
                        label: 'Dynamic Value',
                        mandatory: false,
                    }),
                    computedValue: StringColumn({
                        label: 'Computed Value',
                        mandatory: false,
                    }),
                },
                label: 'Mixed Data',
                mandatory: false,
            }),

            // ==== Simple string variable for comparison ====
            simpleString: StringColumn({
                label: 'Simple String',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['comprehensive_test_trigger'], annotation: 'Trigger on incident creation' },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'true',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // ==== TEST 1: Happy Path - Object literals ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test1_happy_path_literals'],
                annotation: 'TEST 1: Happy Path - Object literals assigned to FlowObject/FlowArray',
            },
            params.flowVariables,
            {
                userInfo: {
                    name: 'John Doe',
                    email: 'john.doe@example.com',
                    age: 30,
                    isActive: true,
                },
                tags: [{ value: 'urgent' }, { value: 'important' }, { value: 'review' }],
                simpleString: 'Test completed',
            }
        )

        // ==== TEST 2: Datapills in FlowObject fields ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test2_datapills_in_fields'],
                annotation: 'TEST 2: Datapills used in FlowObject field values',
            },
            params.flowVariables,
            {
                userInfo: {
                    name: wfa.dataPill(params.trigger.current.assigned_to.name, 'string'),
                    email: wfa.dataPill(params.trigger.current.assigned_to.email, 'string'),
                    age: wfa.dataPill(params.trigger.current.number, 'integer'),
                    isActive: wfa.dataPill(params.trigger.current.business_impact, 'boolean'),
                },
            }
        )

        // ==== TEST 3: Nested FlowObject with literals ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test3_nested_object_literals'],
                annotation: 'TEST 3: Nested FlowObject with literal values',
            },
            params.flowVariables,
            {
                config: {
                    settings: {
                        timeout: 60,
                        retries: 5,
                        enabled: true,
                    },
                    description: 'Production configuration',
                },
            }
        )

        // ==== TEST 4: Nested FlowObject with datapills ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test4_nested_object_datapills'],
                annotation: 'TEST 4: Nested FlowObject with datapills in nested fields',
            },
            params.flowVariables,
            {
                config: {
                    settings: {
                        timeout: wfa.dataPill(params.trigger.current.priority, 'integer'),
                        retries: 3,
                        enabled: true,
                    },
                    description: wfa.dataPill(params.trigger.current.short_description, 'string'),
                },
            }
        )

        // ==== TEST 5: FlowObject with nested FlowArray ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test5_object_with_nested_array'],
                annotation: 'TEST 5: FlowObject containing nested FlowArray',
            },
            params.flowVariables,
            {
                project: {
                    name: 'Infrastructure Upgrade',
                    tasks: [
                        { taskName: 'Setup servers' },
                        { taskName: 'Configure network' },
                        { taskName: 'Deploy apps' },
                    ],
                },
            }
        )

        // ==== TEST 6: Empty and null values in FlowObject ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test6_empty_null_values'],
                annotation: 'TEST 6: Empty strings, null values, and undefined in FlowObject',
            },
            params.flowVariables,
            {
                partialData: {
                    field1: 'Has value',
                    field2: '',
                    field3: null,
                },
            }
        )

        // ==== TEST 7: Primitive datapill assigned to FlowObject (edge case) ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test7_primitive_to_flowobject'],
                annotation: 'TEST 7: Primitive datapill assigned to FlowObject variable (should create empty children)',
            },
            params.flowVariables,
            {
                callerData: wfa.dataPill(params.trigger.current.caller_id, 'reference'),
            }
        )

        // ==== TEST 8: Empty FlowArray ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test8_empty_array'],
                annotation: 'TEST 8: Empty array assigned to FlowArray',
            },
            params.flowVariables,
            {
                emptyList: [],
            }
        )

        // ==== TEST 9: Mixed literals and datapills in same FlowObject ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test9_mixed_literals_datapills'],
                annotation: 'TEST 9: FlowObject with mix of literal values and datapills',
            },
            params.flowVariables,
            {
                mixedData: {
                    staticValue: 'Static literal value',
                    dynamicValue: wfa.dataPill(params.trigger.current.number, 'string'),
                    computedValue: `Incident: ${wfa.dataPill(params.trigger.current.number, 'string')}`,
                },
            }
        )

        // ==== TEST 10: Template expressions in FlowObject ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test10_template_expressions'],
                annotation: 'TEST 10: Template expressions in FlowObject fields',
            },
            params.flowVariables,
            {
                userInfo: {
                    name: `User: ${wfa.dataPill(params.trigger.current.caller_id, 'reference')}`,
                    email: `${wfa.dataPill(params.trigger.current.number, 'string')}@example.com`,
                    age: 35,
                    isActive: true,
                },
            }
        )

        // ==== TEST 11: Deeply nested datapills in FlowArray ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test11_datapills_in_array'],
                annotation: 'TEST 11: Datapills inside FlowArray elements',
            },
            params.flowVariables,
            {
                tags: [
                    { value: wfa.dataPill(params.trigger.current.priority, 'string') },
                    { value: wfa.dataPill(params.trigger.current.state, 'string') },
                    { value: `Status: ${wfa.dataPill(params.trigger.current.incident_state, 'string')}` },
                ],
            }
        )

        // ==== TEST 12: FlowArray with mixed literal and datapill objects ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test12_array_mixed_elements'],
                annotation: 'TEST 12: FlowArray with some literal objects and some with datapills',
            },
            params.flowVariables,
            {
                tags: [
                    { value: 'literal-tag-1' },
                    { value: wfa.dataPill(params.trigger.current.urgency, 'string') },
                    { value: 'literal-tag-2' },
                    { value: wfa.dataPill(params.trigger.current.impact, 'string') },
                ],
            }
        )

        // ==== TEST 13: All empty values in FlowObject ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test13_all_empty_values'],
                annotation: 'TEST 13: FlowObject with all fields empty/null',
            },
            params.flowVariables,
            {
                partialData: {
                    field1: '',
                    field2: null,
                    field3: null,
                },
            }
        )

        // ==== TEST 14: Identifier datapill to FlowObject ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test14_identifier_to_flowobject'],
                annotation: 'TEST 14: Identifier shape (params.trigger.current) assigned to FlowObject',
            },
            params.flowVariables,
            {
                callerData: wfa.dataPill(params.trigger.current, 'reference'),
            }
        )

        // ==== TEST 15: Property access deeply nested ====
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['test15_deep_property_access'],
                annotation: 'TEST 15: Deeply nested property access in FlowObject',
            },
            params.flowVariables,
            {
                config: {
                    settings: {
                        timeout: wfa.dataPill(params.trigger.current.priority, 'integer'),
                        retries: wfa.dataPill(params.trigger.current.urgency, 'integer'),
                        enabled: wfa.dataPill(params.trigger.current.active, 'boolean'),
                    },
                    description: wfa.dataPill(params.trigger.current.short_description, 'string'),
                },
            }
        )

        // ==== Final log action ====

        wfa.action(
            action.core.log,
            { $id: Now.ID['log_all_tests_complete_1'] },
            {
                log_level: 'info',
                log_message: 'All FlowObject/FlowArray tests completed successfully',
            }
        )
    }
)
